input.command:
cd /tmp && perl -e '
my @t = ("A\xC0B://h", "\xFF\xFE://h", "A\tB://h", "A\nB://h", "HTTP\r://h", "A\x01B://h", "\x00", "AB://\xC0\xDF", "a\x7fb://c");
for my $u (@t) {
  (my $d = $u) =~ s/([^\x20-\x7e])/sprintf("\\x%02X",ord($1))/ge;
  print "=== [$d]\n";
  my $pid = open(my $fh, "-|");
  if ($pid == 0) { exec("/workspace/dataset/test5_executable", $u); exit 127; }
  my $i=0; while (my $l = <$fh>) { $i++; chomp $l; (my $e=$l) =~ s/([^\x20-\x7e])/sprintf("\\x%02X",ord($1))/ge; print "  $i: [$e]\n"; }
  close $fh;
}'
